import express from 'express';
import cors from 'cors';
import { z } from 'zod';

const app = express();
app.use(express.json());
app.use(cors({ origin: 'http://localhost:4200/' }));

const TaskInput = z.object({
  title: z.string().min(1),
  priority: z.enum(['low', 'medium', 'high']).default('medium'),
});

const tasks = [{ id: 1, title: 'Write README', priority: 'low', done: false }];
let nextId = 2;

function validate(schema) {
  return (req, res, next) => {
    const result = schema.safeParse(req.body);
    if (!result.success) {
      res.status(400).json({ errors: result.error.issues });
    }
    req.body = result.data;
    next();
  };
}

async function fakeDbSave(task) {
  await new Promise((r) => setTimeout(r, 50));
  if (task.title === 'boom') throw new Error('DB write failed');
  tasks.push(task);
  return task;
}

app.post('/tasks', validate(TaskInput), (req, res) => {
  const task = { id: nextId++, ...req.body, done: false };
  fakeDbSave(task);
  res.status(201).json(task);
});

app.get('/tasks', (req, res) => {
  const { done } = req.query;
  const list = done === undefined ? tasks : tasks.filter((t) => t.done === done);
  res.json(list);
});

app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({ error: 'Something went wrong' });
});

app.listen(3000, () => console.log('API on http://localhost:3000'));
